import React from "react";
import EventCard from "./events/EventCard";

const Events = () => {
  const sampleEvents = [
    { id: 1, title: "Health Camp", description: "Free medical checkup for villagers" },
    { id: 2, title: "Tree Plantation Drive", description: "Join us to plant 500 trees" },
    { id: 3, title: "Education for All", description: "Support rural children's education" },
  ];

  return (
    <div className="events-container">
      <h2>Upcoming Events</h2>

      <div className="events-grid">
        {sampleEvents.map(event => (
          <EventCard key={event.id} event={event} />
        ))}
      </div>
    </div>
  );
};

export default Events;
